import HTMLParser from "@utils/html_parser";
import template from "./card.html";
export default class Card {
    constructor() {
        this.element = HTMLParser.parse(template);
        this.title = this.element.querySelector(".card-title");
        this.text = this.element.querySelector(".card-text");
        this.image = this.element.querySelector(".card-img-top");
    }
    getElement() {
        return this.element;
    }
    setTitle(title) {
        this.title.textContent = title;
    }
    setText(text) {
        this.text.textContent = text;
    }
    setImage(imageUrl, altText = "") {
        this.image.src = imageUrl;
        this.image.alt = altText;
    }
}
